@'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {parse} from 'yaml';
import {validateRegistry,registryBindingManifestDigest,canonicalJson,sha256,bindingDigestFor} from './src/validate.ts';
const full=parse(readFileSync('authority-enforcement-registry.yaml','utf8'));
const head=d=>d.reconciliations.at(-1);
const editCommand=(r,p,fn)=>{r.observedEvidence=r.observedEvidence.map(e=>{if(e.kind!=='command-result')return e;const c=JSON.parse(e.reference);if(!c.commandId.startsWith(p))return e;fn(c);const reference=canonicalJson(c);return {...e,reference,digest:sha256(reference)};});};
const check=(name,d,pattern)=>{const r=validateRegistry(d);if(pattern){assert.equal(r.valid,false,name);assert(r.violations.some(v=>pattern.test(v.message)),JSON.stringify(r));}else assert.deepEqual(r.violations,[],name);console.log(JSON.stringify({name,valid:r.valid,codes:[...new Set(r.violations.map(v=>v.code))],matching:pattern?r.violations.filter(v=>pattern.test(v.message)).map(v=>v.message):[]}));};
check('shipped positive control',full);
let d=structuredClone(full);d.reconciliations.splice(18,1);check('delete former head',d,/required rework migration 'registry-rework-40394be' is missing/);
d=structuredClone(full);d.reconciliations[18].scopedDisposition+=' rewritten';check('rewrite canonical former head',d,/differs from its complete canonical record manifest/);
d=structuredClone(full);d.reconciliations.pop();editCommand(head(d),'superseding-binding-manifest',c=>c.resultDigest=registryBindingManifestDigest(d));check('delete current head and reanchor promoted record',d,/cannot be the migration chain head/);
d=structuredClone(full);head(d).observedEvidence.find(e=>e.kind==='git-commit'&&e.reference===d.sourceSnapshotCommit).reference='b'.repeat(40);check('fabricate unbound head Git reference',d,/neither bound by its prior binding-manifest command nor equal/);
d=structuredClone(full);editCommand(head(d),'superseding-binding-manifest',c=>c.resultDigest=c.inputDigest);check('head self cycle',d,/contains a cycle/);
d=structuredClone(full);const fork=structuredClone(head(d));fork.reconciliationId='registry-rework-independent-fork';d.reconciliations.push(fork);check('fork same predecessor',d,/chain forks/);
function retire(d,subject){let n=0;for(const r of d.rules)if(r.authoritySubject===subject&&r.retirementState==='active-reading'){r.retirementState='historical-only';r.bindingDigest=bindingDigestFor(r);n++;}assert(n>0);}
function append(d,id){const prev=head(d),old=JSON.parse(prev.observedEvidence.find(e=>e.kind==='command-result'&&JSON.parse(e.reference).commandId.startsWith('superseding-binding-manifest')).reference).resultDigest;const next=registryBindingManifestDigest(d);assert.notEqual(old,next);const commit='a'.repeat(40);const cmd=(commandId,inputDigest,resultDigest)=>{const reference=canonicalJson({tool:'@foreman-line/authority-registry',toolVersion:'0.1.0',commandId,inputDigest,resultDigest,exitCode:0,actorClass:'coordinator'});return {kind:'command-result',reference,digest:sha256(reference)}};d.reconciliations.push({reconciliationId:id,topic:'Independent review migration probe.',observedRefs:[prev.observedRefs[0]],observedEvidence:[{kind:'git-commit',reference:commit,digest:sha256('prior')},{kind:'git-commit',reference:d.sourceSnapshotCommit,digest:sha256('source')},cmd('registry-binding-manifest-independent',sha256(commit),old),cmd('superseding-binding-manifest-independent',old,next)],authoritativeRuleIds:prev.authoritativeRuleIds,scopedDisposition:'Independent review amendment.',unresolvedConsequence:'Future binding changes require another typed prior-to-new migration record.',migrationStatus:'superseded-by-amendment',supersedingEvidence:prev.observedRefs[0]});return d;}
d=structuredClone(full);retire(d,'gate3.merge-authority');append(d,'registry-rework-independent1');check('single well-formed successor admitted',d);
const demoted=structuredClone(d);demoted.reconciliations[19].scopedDisposition+=' rewritten';check('new shipped head protected on future demotion',demoted,/differs from its complete canonical record manifest/);
retire(d,'goal.exit-merge');append(d,'registry-rework-independent2');check('second unregistered successor refused',d,/registry-rework-independent1.*differs from its complete canonical record manifest/);
console.log('INDEPENDENT_PROBES=10 PASS');
'@ | & 'D:/nodejs_symlinks/node.exe' --import tsx --input-type=module -
Write-Output "DIRECT_EXIT=$LASTEXITCODE"
